def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = background(g)
    cols = [int(c) for c in np.unique(g) if c not in (bg, 2, 4)]
    emit(g.copy(), "Input: coloured paths with gaps, 2-markers at corners, 4-markers and unreliable crossings.")

    def build(c):
        s = set()
        def isc(y, x):
            return 0 <= y < H and 0 <= x < W and g[y, x] in (c, 2)
        for axis in (0, 1):
            L = H if axis == 0 else W
            for i in range(L):
                line = g[i, :] if axis == 0 else g[:, i]
                n = len(line)
                pos = (lambda j: (i, j)) if axis == 0 else (lambda j: (j, i))
                def blocked(j):
                    y, x = pos(j)
                    if g[y, x] != c:
                        return False
                    if axis == 0:
                        return isc(y - 1, x) and isc(y + 1, x)
                    return isc(y, x - 1) and isc(y, x + 1)
                xs = [j for j in range(n) if line[j] in (c, 2)]
                groups = []
                for j in xs:
                    if groups and (j - groups[-1][-1] == 1 or
                                   (j - groups[-1][-1] == 2 and not blocked(j) and not blocked(groups[-1][-1]))):
                        groups[-1].append(j)
                    else:
                        groups.append([j])
                for grp in groups:
                    if sum(line[j] == c for j in grp) < 2:
                        continue
                    for j in range(grp[0], grp[-1] + 1):
                        s.add(pos(j))
        return s

    S = {c: build(c) for c in cols}

    extension_axes = {}
    def paint(Sd):
        def reaches(a, b, edges):
            seen = {a}; todo = [a]
            while todo:
                p = todo.pop()
                for u, v in edges:
                    if u == p and v not in seen:
                        seen.add(v); todo.append(v)
            return b in seen
        def axis(c, y, x):
            horizontal = (y, x-1) in Sd[c] and (y, x+1) in Sd[c]
            vertical = (y-1, x) in Sd[c] and (y+1, x) in Sd[c]
            return 'h' if horizontal and not vertical else 'v' if vertical and not horizontal else None
        edges = set()
        # Blank crossings: strand parallel to a marker extension takes precedence.
        for i, c in enumerate(cols):
            for d in cols[i+1:]:
                for y, x in sorted(Sd[c] & Sd[d]):
                    if g[y, x] != bg:
                        continue
                    ac, ad = axis(c, y, x), axis(d, y, x)
                    preferred = set()
                    for col, local_axis in [(c, ac), (d, ad)]:
                        if local_axis in extension_axes.get(col, set()):
                            preferred.add(local_axis)
                    if not preferred:
                        preferred = {a for axes in extension_axes.values() for a in axes}
                    if ac in preferred and ad not in preferred:
                        edge = (d, c)
                    elif ad in preferred and ac not in preferred:
                        edge = (c, d)
                    else:
                        continue
                    if not reaches(edge[1], edge[0], edges):
                        edges.add(edge)
        # Visible crossings: reverse the input's layering unless it conflicts.
        for i, c in enumerate(cols):
            for d in cols[i+1:]:
                for y, x in sorted(Sd[c] & Sd[d]):
                    if int(g[y, x]) == c:
                        edge = (c, d)
                    elif int(g[y, x]) == d:
                        edge = (d, c)
                    else:
                        continue
                    if not reaches(edge[1], edge[0], edges):
                        edges.add(edge)
        order = []; remaining = set(cols)
        while remaining:
            available = [c for c in remaining if not any(b == c and a in remaining for a, b in edges)]
            if not available:
                raise ValueError('Conflicting layer constraints')
            c = min(available, key=lambda c: (-len(Sd[c]), c))
            order.append(c); remaining.remove(c)
        out = np.full_like(g, bg)
        for c in order:
            for y, x in Sd[c]:
                out[y, x] = c
        return out

    emit(paint(S), "Repaired paths: one-cell gaps bridged and 2-markers absorbed into the path running through them.")

    fours = list(zip(*np.where(g == 4)))
    for (y, x) in fours:
        done = False
        for dy, dx in ((0, 1), (0, -1), (1, 0), (-1, 0)):
            K = (int(y + dy), int(x + dx))
            O = (K[0] + dy, K[1] + dx)
            for c in cols:
                if K in S[c] and O in S[c]:
                    rest = S[c] - {K}
                    mask = np.zeros((H, W), bool)
                    for (a, b) in rest:
                        mask[a, b] = True
                    for comp in components(mask):
                        if O in comp:
                            for cell in comp:
                                S[c].discard(cell)
                            break
                    yy, xx = K
                    while 0 <= yy < H and 0 <= xx < W:
                        S[c].add((yy, xx))
                        yy -= dy
                        xx -= dx
                    extension_axes.setdefault(c, set()).add("h" if dx else "v")
                    done = True
                    break
            if done:
                break
        if done:
            emit(paint(S), f"4-marker at ({y},{x}): limb beyond the corner removed, path redirected through the marker to the edge.")

    out = paint(S)
    emit(out, "Final: layer order from marker-directed blank crossings and non-conflicting reversed visible crossings; length breaks ties.")
    return out
